use std::collections::HashMap;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Map value -> earliest index where it appears.
    // Scanning j from left to right ensures that once we find a match,
    // it is the lexicographically smallest pair (p, q).
    let mut first_index: HashMap<u32, usize> = HashMap::new();

    for j in 0..n {
        let x = nums[j];

        if let Some(&i) = first_index.get(&target.wrapping_sub(x)) {
            // i < j because i was inserted from an earlier position.
            return (i, j);
        }

        // Keep the earliest index for each value to minimize the first index.
        first_index.entry(x).or_insert(j);
    }

    // Problem statement guarantees a solution exists.
    unreachable!("No two sum solution found, but one was guaranteed to exist");
}